window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6af67a15735d95d9"]={"versions": [{"id": "FIG-6af67a15735d95d9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Modell / Feature-Baum (Variabilitäts- und Domänenmodellierung nach FODA / Czarnecki-Notation gemäß AUTOSAR Foundation <code>FO_TR_Features</code>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition der hierarchischen Dekomposition und Variabilität des FlexRay-Kommunikationsstacks im AUTOSAR-Standard (Release R24-11).\n</li><li><strong>Funktionale Einordnung:</strong> Verortung auf Anforderungsebene (Foundation/Classic Platform). Es modelliert die funktionale Abhängigkeit der AUTOSAR-Zeitsynchronisation über FlexRay gegenüber der Basis-Kommunikationsinfrastruktur.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Feature-Knoten):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00156</code> (<em>Parent-Feature</em>): <code>FlexRay</code> – repräsentiert die basale FlexRay-Kommunikationsfunktionalität (umfassend MCAL-Treiber <code>Fr</code>, Abstraktionsschicht <code>FrIf</code>, Zustandsmanager <code>FrSM</code> und Transportprotokoll <code>FrTp</code>).\n</li><li><code>FO_TR_FEAT_00239</code> (<em>Child-Feature</em>): <code>FlexRay_Time_Sync</code> – spezifiziert die globale Zeitsynchronisation über den FlexRay-Bus (AUTOSAR Time Synchronization Architecture).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Semantik:</strong>\n<ul class=\"fig-list\"><li><strong>Hierarchische Kante mit ungefülltem Kreis (Hollow Circle):</strong> Kennzeichnet ein <strong>optionales Sub-Feature</strong> (<em>Optional Feature Dependency</em>, Kardinalität <code>0..1</code>).\n</li><li><strong>Bedingung:</strong> <code>FO_TR_FEAT_00239</code> setzt zwingend das Vorhandensein des übergeordneten Features <code>FO_TR_FEAT_00156</code> voraus (<code>FO_TR_FEAT_00239 ⇒ FO_TR_FEAT_00156</code>). Ein System kann FlexRay (<code>FO_TR_FEAT_00156</code>) autark betreiben, ohne <code>FlexRay_Time_Sync</code> zu aktivieren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Strukturmodell:</strong> Kein direkter Laufzeit- oder Call-Stack-Ablauf abgebildet.\n</li><li><strong>Funktionale Interaktion bei Feature-Aktivierung:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00239</code> aktiviert zur Laufzeit das Zusammenspiel zwischen <code>FrIf</code>, dem zeitsynchronisierenden Protokollmodul <code>FrTSyn</code> (FlexRay Time Synchronization) und dem Basissoftware-Modul <code>StbM</code> (Synchronized Time-Base Manager).\n</li><li>Nutzt clusterintern die hardwarenahe FlexRay-Macrotick/Microtick-Zeitsynchronisation und überträgt über globale Zeit-PDUs (Sync-/Follow-Up-Frames) absolute Zeitstempel (Global Time Domains) an Slaves bzw. Gateway-Knoten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Stack-Konfiguration (BSW / Ecuc):</strong>\n<ul class=\"fig-list\"><li><strong>Inaktiv (<code>FO_TR_FEAT_00239</code> abgewählt):</strong> Nur Basistreiber und Interface (<code>Fr</code>, <code>FrIf</code>, <code>FrSM</code>) müssen im BSW-Stack konfiguriert und gelinkt werden. <code>FrTSyn</code> entfällt vollständig; RAM-/Flash-Footprint sowie zyklische <code>FrTSyn_MainFunction</code>-Pollings werden eingespart.\n</li><li><strong>Aktiv (<code>FO_TR_FEAT_00239</code> angewählt):</strong> \n<ul class=\"fig-list\"><li>Zwingende Integration des BSW-Moduls <code>FrTSyn</code> inkl. Anbindung an den <code>StbM</code>.\n</li><li>Konfiguration der Time-Base-Rolle (<code>FrTSynGlobalTimeDomain</code>: Master vs. Slave) und Parametrierung der Synchronisations-PDUs im <code>FrIf</code> und <code>PduR</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>API- &amp; Systemverträge:</strong>\n<ul class=\"fig-list\"><li>Applikationen greifen für synchrone Zeitfunktionen ausschließlich über standardisierte <code>StbM</code>-APIs (z. B. <code>StbM_GetCurrentTime()</code>) zu; kein direkter Treiber-Durchgriff auf FlexRay-Register oder <code>FrTSyn</code>.\n</li></ul>\n</li></ul>"}, {"id": "FIG-10d8df4906b71f36", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Modell / Feature-Baum (Variabilitäts- und Domänenmodellierung nach FODA / Czarnecki-Notation gemäß AUTOSAR Foundation <code>FO_TR_Features</code>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition der hierarchischen Dekomposition und Variabilität des FlexRay-Kommunikationsstacks im AUTOSAR-Standard (Release R25-11).\n</li><li><strong>Funktionale Einordnung:</strong> Verortung auf Anforderungsebene (Foundation/Classic Platform). Es modelliert die funktionale Abhängigkeit der Zeitsynchronisation sowie des Transportprotokolls über FlexRay gegenüber der Basis-Kommunikationsinfrastruktur.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten (Feature-Knoten):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00156</code> (<em>Parent-Feature</em>): <code>FlexRay</code> – repräsentiert die basale FlexRay-Kommunikationsfunktionalität (umfassend MCAL-Treiber <code>Fr</code>, Abstraktionsschicht <code>FrIf</code> und Zustandsmanager <code>FrSM</code>).\n</li><li><code>FO_TR_FEAT_00239</code> (<em>Child-Feature</em>): <code>FlexRay_Time_Sync</code> – spezifiziert die globale Zeitsynchronisation über den FlexRay-Bus (AUTOSAR Time Synchronization Architecture).\n</li><li><code>FO_TR_FEAT_00265</code> (<em>Child-Feature</em>): <code>FlexRay_TP</code> – spezifiziert das FlexRay-Transportprotokoll (Segmentierung, Reassemblierung und Flow Control für Diagnosedaten und große Datensätze).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Semantik:</strong>\n<ul class=\"fig-list\"><li><strong>Hierarchische Kanten mit ungefülltem Kreis (Hollow Circle):</strong> Kennzeichnen jeweils <strong>optionale Sub-Features</strong> (<em>Optional Feature Dependency</em>, Kardinalität jeweils <code>0..1</code>).\n</li><li><strong>Bedingungen:</strong> Sowohl <code>FO_TR_FEAT_00239</code> als auch <code>FO_TR_FEAT_00265</code> setzen zwingend das übergeordnete Feature <code>FO_TR_FEAT_00156</code> voraus (<code>FO_TR_FEAT_00239 ⇒ FO_TR_FEAT_00156</code>, <code>FO_TR_FEAT_00265 ⇒ FO_TR_FEAT_00156</code>). Beide Child-Features können unabhängig voneinander aktiviert oder deaktiviert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Strukturmodell:</strong> Kein direkter Laufzeit- oder Call-Stack-Ablauf abgebildet.\n</li><li><strong>Funktionale Interaktion bei Feature-Aktivierung:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00239</code>: Aktiviert das Zusammenspiel zwischen <code>FrIf</code>, dem zeitsynchronisierenden Protokollmodul <code>FrTSyn</code> (FlexRay Time Synchronization) und dem Basissoftware-Modul <code>StbM</code> (Synchronized Time-Base Manager) zur Verteilung globaler Zeitstempel.\n</li><li><code>FO_TR_FEAT_00265</code>: Aktiviert das Modul <code>FrTp</code> zur PDU-Segmentierung und Flusssteuerung zwischen dem <code>PduR</code> (bzw. <code>Dcm</code>) und dem <code>FrIf</code> für Botschaftslängen über der maximalen FlexRay-Payload (z. B. ISO 10681-2).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Stack-Konfiguration (BSW / Ecuc):</strong>\n<ul class=\"fig-list\"><li><strong>Basiskonfiguration (<code>FO_TR_FEAT_00156</code> aktiv, Child-Features inaktiv):</strong> Es werden lediglich <code>Fr</code>, <code>FrIf</code> und <code>FrSM</code> eingebunden und konfiguriert; <code>FrTSyn</code> und <code>FrTp</code> entfallen vollständig.\n</li><li><strong>Aktivierung <code>FO_TR_FEAT_00239</code> (<code>FlexRay_Time_Sync</code>):</strong> Zwingende Konfiguration von <code>FrTSyn</code> inkl. <code>StbM</code>-Anbindung, Festlegung der Time-Domain-Rollen (Master/Slave) und Parametrierung der Zeit-PDUs.\n</li><li><strong>Aktivierung <code>FO_TR_FEAT_00265</code> (<code>FlexRay_TP</code>):</strong> Zwingende Integration des BSW-Moduls <code>FrTp</code>, Konfiguration der Transportkanäle, Verbindungsdeskriptoren (Tx/Rx-NSdu) und PDU-Routingbeziehungen im <code>PduR</code>.\n</li></ul>\n</li><li><strong>API- &amp; Systemverträge:</strong>\n<ul class=\"fig-list\"><li>Standardisierte Zugriffspfade: Zeitsynchronisation erfolgt über <code>StbM</code>-APIs; segmentierte Diagnose- und Applikationsdatenkommunikation wird über standardisierte PDU-Router-Schnittstellen abgewickelt.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-6af67a15735d95d9", "to": "FIG-10d8df4906b71f36", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Feature-Modellstruktur:</strong> Neues optionales Sub-Feature <code>FO_TR_FEAT_00265</code> (<code>FlexRay_TP</code>) unterhalb von Parent-Feature <code>FO_TR_FEAT_00156</code> (<code>FlexRay</code>) mit Kardinalität <code>0..1</code> (Hollow Circle) hinzugefügt.\n</li></ul>"}]};
